inputs = ['guc', 'wjyd', 'ckahkz', 'cey', 'zgjk']
outputs = ['gdc', 'wvyd', 'ckaykibj', 'cey', 'ibjgvk']

print("Detailed character-by-character comparison:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{out}'")
    print("  Pos: ", end="")
    for j in range(max(len(inp), len(out))):
        if j < len(inp) and j < len(out):
            print(f"{j:2d}", end=" ")
        elif j < len(inp):
            print(f"{j:2d}", end=" ")
        else:
            print(f"  ", end=" ")
    print()
    print("  Inp: ", end="")
    for j in range(max(len(inp), len(out))):
        if j < len(inp):
            print(f"'{inp[j]}' ", end="")
        else:
            print("   ", end="")
    print()
    print("  Out: ", end="")
    for j in range(max(len(inp), len(out))):
        if j < len(out):
            print(f"'{out[j]}' ", end="")
        else:
            print("   ", end="")
    print()

